CREATE TABLE IF NOT EXISTS companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('manager','technician')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),name text NOT NULL,phone text,address text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),customer_id uuid NOT NULL REFERENCES customers(id),technician_id uuid REFERENCES users(id),title text NOT NULL,description text,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','assigned','in_progress','completed','cancelled')),scheduled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),order_id uuid NOT NULL REFERENCES orders(id),technician_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('checkin','checkout')),latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy double precision,photo_data text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),order_id uuid NOT NULL REFERENCES orders(id),technician_id uuid NOT NULL REFERENCES users(id),notes text NOT NULL,checklist jsonb NOT NULL DEFAULT '[]',photos jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_company_idx ON orders(company_id,status);
CREATE INDEX IF NOT EXISTS visits_order_idx ON visits(company_id,order_id,created_at);
CREATE INDEX IF NOT EXISTS reports_order_idx ON reports(company_id,order_id);
